<?php foreach(['aapanel'=>'aaPanel','servers'=>'CajeerServers'] as $source=>$label): $o=$obs[$source]??[]; ?><p><b><?= h($label) ?></b> · <?= !empty($o['fresh'])?'Свежие данные':'Неактуально / нет успешной проверки' ?> · последняя попытка <?= isset($o['attempt_at'])?h(gmdate('Y-m-d H:i:s',(int)$o['attempt_at'])):'—' ?> · последний успех <?= isset($o['success_at'])?h(gmdate('Y-m-d H:i:s',(int)$o['success_at'])):'—' ?> UTC</p><?php if(!empty($o['error'])): ?><p class="planning-warning"><?= h($o['error']) ?></p><?php endif; endforeach ?>
